import{_ as l,a0 as p,w as d,s as r,ao as o,I as n,x as a,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何使用 grubby 更改 RHEL 8 和 9 的默认内核 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 grubby 更改 RHEL 8 和 9 的默认内核 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 grubby 更改 RHEL 8 和 9 的默认内核 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 grubby 更改 RHEL 8 和 9 的默认内核 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230816 How to Change the default kernel in RHEL 8 and 9","title":"如何使用 grubby 更改 RHEL 8 和 9 的默认内核","tag":"202309","desc":""},"relativePath":"202309/20230816 How to Change the default kernel in RHEL 8 and 9.md","filePath":"[post].md"}'),h={name:"202309/20230816 How to Change the default kernel in RHEL 8 and 9.md"};function g(b,s,u,c,k,f){const e=p("Link");return d(),r("div",null,[s[15]||(s[15]=o(`<h1 id="如何使用-grubby-更改-rhel-8-和-9-的默认内核" tabindex="-1">如何使用 grubby 更改 RHEL 8 和 9 的默认内核 <a class="header-anchor" href="#如何使用-grubby-更改-rhel-8-和-9-的默认内核" aria-label="Permalink to “如何使用 grubby 更改 RHEL 8 和 9 的默认内核”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/01/105123phdy0f0fmgavquqq.jpg" alt=""></p><p>通常 Linux 系统会默认引导系统进入最新安装的内核，并保留最新的 3 个 Linux 内核引导条目。</p><p>假设你已经执行了 <code>yum update</code>，并且新的内核作为更新的一部分已经安装了。这时，由于这个新内核与应用程序不兼容，它会阻止应用程序启动。</p><p>想要暂时解决这个问题，你应该还是引导系统进入旧内核。</p><p>在本文中，我们将向您展示如何使用 <code>grubby</code> 工具将旧的内核版本设置为 RHEL 8 和 RHEL 9 系统上的默认版本。</p><h3 id="grubby-是什么" tabindex="-1">grubby 是什么 <a class="header-anchor" href="#grubby-是什么" aria-label="Permalink to “grubby 是什么”">​</a></h3><p><code>grubby</code> 是一个命令行工具，用于在多个架构上更新和显示引导加载配置文件的信息。</p><h3 id="检查当前引导的内核" tabindex="-1">检查当前引导的内核 <a class="header-anchor" href="#检查当前引导的内核" aria-label="Permalink to “检查当前引导的内核”">​</a></h3><p>你可以使用如下的 <code>uname</code> 命令来检查当前引导/加载的内核。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># uname -r</span></span>
<span class="line"><span>4.18.0-477.13.1.el8_8.x86_64</span></span></code></pre></div><h3 id="列出默认内核" tabindex="-1">列出默认内核 <a class="header-anchor" href="#列出默认内核" aria-label="Permalink to “列出默认内核”">​</a></h3><p>使用 <code>grubby</code> 验证默认内核版本，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --default-kernel</span></span>
<span class="line"><span>/boot/vmlinuz-4.18.0-477.13.1.el8_8.x86_64</span></span></code></pre></div><p>要获取当前默认内核的索引号，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --default-index</span></span>
<span class="line"><span>0</span></span></code></pre></div><h3 id="检查已安装的内核" tabindex="-1">检查已安装的内核 <a class="header-anchor" href="#检查已安装的内核" aria-label="Permalink to “检查已安装的内核”">​</a></h3><p>要检查已安装的内核的列表，请运行以下命令：</p><p>我们来解释以下的输出信息。最新安装的内核的<strong>条目索引</strong>为 <code>0</code>，接下来的 <strong>较旧的内核</strong> 版本将会是 <code>1</code>，第二个更旧的内核版本将会是 <code>2</code>，而 <strong>救援内核</strong> 的条目索引将会是 <code>3</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --info=ALL | egrep -i &#39;index|title&#39;</span></span>
<span class="line"><span>index=0</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (4.18.0-477.13.1.el8_8.x86_64) 8.8 (Ootpa)&quot;</span></span>
<span class="line"><span>index=1</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (4.18.0-425.19.2.el8_7.x86_64) 8.7 (Ootpa)&quot;</span></span>
<span class="line"><span>index=2</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (4.18.0-425.13.1.el8_7.x86_64) 8.7 (Ootpa)&quot;</span></span>
<span class="line"><span>index=3</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (0-rescue-13iu76884ec5490puc67j8789s249b0c) 8.2 (Ootpa)&quot;</span></span></code></pre></div><h3 id="更改默认内核引导条目" tabindex="-1">更改默认内核引导条目 <a class="header-anchor" href="#更改默认内核引导条目" aria-label="Permalink to “更改默认内核引导条目”">​</a></h3><p>我们可以用两种方式，使用 “内核文件名”，或者使用 “内核条目索引”。我们设置索引号为 <code>1</code> 的 <code>4.18.0-425.19.2.el8_7.x86_64</code> 为默认内核，以此满足应用程序的依赖关系。</p><p>语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default [kernel-filename]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default /boot/vmlinuz-4.18.0-425.19.2.el8_7.x86_64</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default vmlinuz-4.18.0-425.19.2.el8_7.x86_64</span></span></code></pre></div><p>使用内核条目索引更改默认的内核引导：</p><p>语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default-index=[kernel-entry-index]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default-index=1</span></span></code></pre></div><h3 id="重启系统" tabindex="-1">重启系统 <a class="header-anchor" href="#重启系统" aria-label="Permalink to “重启系统”">​</a></h3><p>重启系统，检查旧内核是否持久更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># init 6</span></span></code></pre></div><h3 id="验证更改" tabindex="-1">验证更改 <a class="header-anchor" href="#验证更改" aria-label="Permalink to “验证更改”">​</a></h3><p>让我们检查一下在上一步中添加的内核是否生效了。好了，按我们的预期使用了较旧的内核 “N-1” 进行引导了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># uname -r</span></span>
<span class="line"><span>4.18.0-425.19.2.el8_7.x86_64</span></span>
<span class="line"><span># grubby --default-kernel</span></span>
<span class="line"><span>/boot/vmlinuz-4.18.0-425.19.2.el8_7.x86_64</span></span></code></pre></div><p>要检查所有内核的详细信息，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --info=ALL</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2023/06/changing-default-kernel-rhel-8-rhel-9-1024x494.jpg" alt=""></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本教程中，我们展示了如何使用 <code>grubby</code> 工具在 RHEL 8 和 RHEL 9 系统上将旧版本内核设置为默认。</p><p>如果有任何问题或反馈，欢迎在下方发表评论。</p><p><em>（题图：MJ/9204b9c1-c1ad-4694-b2f6-a7d983976d22）</em></p><hr>`,47)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.2daygeek.com/changing-default-kernel-rhel-8-rhel-9/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/changing-default-kernel-rhel-8-rhel-9/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://www.2daygeek.com/author/rasool/"},{default:t(()=>[...s[2]||(s[2]=[a("Rasool Cool",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(e,{href:"https://github.com/onionstalgia"},{default:t(()=>[...s[4]||(s[4]=[a("onionstalgia",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=l(h,[["render",g]]);export